	@Test
	void deeplyNestedTripleTermsDoNotUseCallStack() throws Exception {
		int depth = 50_000;
		byte[] bytes = document(BinaryQueryResultConstants.FORMAT_VERSION, 1, out -> {
			writeString(out, "value");
			for (int i = 0; i < depth; i++) {
				out.writeByte(BinaryQueryResultConstants.TRIPLE_RECORD_MARKER);
				out.writeByte(BinaryQueryResultConstants.URI_RECORD_MARKER);
				writeString(out, "urn:subject");
				out.writeByte(BinaryQueryResultConstants.URI_RECORD_MARKER);
				writeString(out, "urn:predicate");
			}
			out.writeByte(BinaryQueryResultConstants.PLAIN_LITERAL_RECORD_MARKER);
			writeString(out, "leaf");
			out.writeByte(BinaryQueryResultConstants.TABLE_END_RECORD_MARKER);
		});
		QueryResultCollector collector = new QueryResultCollector();
		BinaryQueryResultParser parser = new BinaryQueryResultParser();
		parser.setQueryResultHandler(collector);

		parser.parseQueryResult(new ByteArrayInputStream(bytes));

		Value value = collector.getBindingSets().get(0).getValue("value");
		for (int i = 0; i < depth; i++) {
			TripleTerm term = (TripleTerm) value;
			assertEquals("urn:subject", term.getSubject().stringValue());
			assertEquals("urn:predicate", term.getPredicate().stringValue());
			value = term.getObject();
		}
		assertEquals("leaf", value.stringValue());
	}

	@Test
	void supportedFormatVersionsRemainReadable() throws Exception {
		for (int version = 1; version <= BinaryQueryResultConstants.FORMAT_VERSION; version++) {
			int currentVersion = version;
			byte[] bytes = document(version, 1, out -> {
				if (currentVersion == 1) {
					out.writeUTF("value");
				} else {
					writeString(out, "value");
				}
				out.writeByte(BinaryQueryResultConstants.PLAIN_LITERAL_RECORD_MARKER);
				if (currentVersion == 1) {
					out.writeUTF("literal");
				} else {
					writeString(out, "literal");
				}
				out.writeByte(BinaryQueryResultConstants.TABLE_END_RECORD_MARKER);
			});
			QueryResultCollector collector = new QueryResultCollector();
			BinaryQueryResultParser parser = new BinaryQueryResultParser();
			parser.setQueryResultHandler(collector);

			parser.parseQueryResult(new ByteArrayInputStream(bytes));

			assertEquals("literal", collector.getBindingSets().get(0).getValue("value").stringValue(),
					"format version " + version);
		}
	}

