	private static byte[] document(int version, int columnCount, RecordWriter records) throws IOException {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		DataOutputStream out = new DataOutputStream(bytes);
		out.write(BinaryQueryResultConstants.MAGIC_NUMBER);
		out.writeInt(version);
		if (version == 2) {
			out.writeByte(0);
		}
		out.writeInt(columnCount);
		records.write(out);
		return bytes.toByteArray();
	}

	private static void writeNamespace(DataOutputStream out, int id, String namespace) throws IOException {
		out.writeByte(BinaryQueryResultConstants.NAMESPACE_RECORD_MARKER);
		out.writeInt(id);
		writeString(out, namespace);
	}

	private static void writeQName(DataOutputStream out, int id, String localName) throws IOException {
		out.writeByte(BinaryQueryResultConstants.QNAME_RECORD_MARKER);
		out.writeInt(id);
		writeString(out, localName);
	}

	private static void writeString(DataOutputStream out, String value) throws IOException {
		byte[] utf8 = value.getBytes(StandardCharsets.UTF_8);
		out.writeInt(utf8.length);
		out.write(utf8);
	}

	@FunctionalInterface
	private interface RecordWriter {
		void write(DataOutputStream out) throws IOException;
	}
